import { MakeLogicType, actions, connect, kea, listeners, path, reducers, selectors } from 'kea'

import { capturePageToolUsed } from '../../browser/extensionTelemetry'
import type { PageToolbarEventsState, PageToolbarState } from '../../messaging/pageToolbarBridge'
import { extensionPageToolbarConnectionLogic } from './extensionPageToolbarConnectionLogic'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface extensionEventsLogicValues {
    pageToolbarState: PageToolbarState | null // extensionPageToolbarConnectionLogic
    eventsState: PageToolbarEventsState | null
    searchText: string
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface extensionEventsLogicActions {
    sendCommand: (message: import('../../messaging/pageToolbarBridge').PageToolbarCommand) => {
        message: import('../../messaging/pageToolbarBridge').PageToolbarCommand
    } // extensionPageToolbarConnectionLogic
    exportEvents: () => {
        value: true
    }
    setSearchText: (searchText: string) => {
        searchText: string
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface extensionEventsLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        eventsState: (pageToolbarState: PageToolbarState | null) => PageToolbarEventsState | null
    }
}

export type extensionEventsLogicType = MakeLogicType<
    extensionEventsLogicValues,
    extensionEventsLogicActions,
    Record<string, any>,
    extensionEventsLogicMeta
>

/** The panel side of the event debugger. The page runs the toolbar's debugger logic, which keeps the events. */
export const extensionEventsLogic = kea<extensionEventsLogicType>([
    path(['toolbar', 'extension', 'extensionEventsLogic']),
    connect(() => ({
        values: [extensionPageToolbarConnectionLogic, ['pageToolbarState']],
        actions: [extensionPageToolbarConnectionLogic, ['sendCommand']],
    })),
    actions({
        setSearchText: (searchText: string) => ({ searchText }),
        exportEvents: true,
    }),
    reducers({
        // The page filters with the search a moment later, so the input keeps what the user typed meanwhile.
        searchText: ['', { setSearchText: (_, { searchText }) => searchText }],
    }),
    selectors({
        eventsState: [
            (s) => [s.pageToolbarState],
            (pageToolbarState: PageToolbarState | null): PageToolbarEventsState | null =>
                pageToolbarState?.events ?? null,
        ],
    }),
    listeners(({ actions }) => ({
        setSearchText: ({ searchText }) =>
            actions.sendCommand({ tool: 'events', command: { type: 'set-events-search', searchText } }),
        exportEvents: () => {
            actions.sendCommand({ tool: 'events', command: { type: 'export-events' } })
            capturePageToolUsed('export-events')
        },
    })),
])
